# Keep prose readable where numeric givens meet words or unit symbols.
import re
def readable(v):
 if isinstance(v,str):
  return re.sub(r'(?<=\d)(?=[A-Za-z]{2,})', ' ', v)
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:readable(x) for k,x in v.items()}
 return v
